onUnmounted(() => {
  if (refreshTimer) {
    clearInterval(refreshTimer)
    refreshTimer = null
  }
})

const apiService = ref({
  status: 'normal',
  requestsCount: 12847,
  uptime: 99.9,
  responseTime: 45
})

