onUnmounted(() => {
  if (refreshTimer) {
    clearInterval(refreshTimer)
    refreshTimer = null
  }
})

const database = ref({
  status: 'connected',
  totalUsers: 5432,
  totalMessages: 98765,
  dbSize: '2.3GB',
  connections: 12
})

// 组件销毁时清理定时器
onUnmounted(() => {
  if (refreshTimer) {
    clearInterval(refreshTimer)
    refreshTimer = null
  }
})

// 机器人进程状态
const botProcesses = ref([])
const processCount = ref(0)

const recentActivities = ref([
  {
    id: 1,
    icon: 'i-heroicons-user-plus',
    message: '新用户注册',
    time: '2分钟前',
    type: 'success',
    status: '成功'
  },
  {
    id: 2,
    icon: 'i-heroicons-exclamation-triangle',
    message: 'API 响应时间较慢',
    time: '5分钟前',
    type: 'warning',
    status: '警告'
  },
  {
    id: 3,
    icon: 'i-heroicons-arrow-path',
    message: '系统自动备份完成',
    time: '10分钟前',
    type: 'success',
    status: '完成'
  },
  {
    id: 4,
    icon: 'i-heroicons-server',
    message: '服务器重启',
    time: '1小时前',
    type: 'info',
    status: '信息'
  }
])

// 定时器引用
let refreshTimer = null

// 生命周期钩子
onMounted(() => {
  // 初始化数据
  refreshData()
  
  // 设置定时刷新
  refreshTimer = setInterval(refreshData, 30000) // 每30秒刷新一次
})

// 组件销毁时清理定时器
onUnmounted(() => {
  if (refreshTimer) {
    clearInterval(refreshTimer)
    refreshTimer = null
  }
})

// 方法
const refreshData = async () => {
  try {
    // 这里可以调用API获取实时数据
    console.log('刷新仪表板数据')
    await fetchBotStatus()
  } catch (error) {
    console.error('刷新数据失败:', error)
  }
}

// 获取机器人状态
const fetchBotStatus = async () => {
  try {
    const response = await $fetch('/api/bot-status')
    if (response.success) {
      botProcesses.value = response.data.processes
      processCount.value = response.data.processCount || response.data.processes.length
    }
  } catch (error) {
    console.error('获取机器人状态失败:', error)
    botProcesses.value = []
    processCount.value = 0
  }
}

// 刷新机器人状态
const refreshBotStatus = async () => {
  await fetchBotStatus()
}

// 格式化日期时间
const formatDateTime = (dateString) => {
  const date = new Date(dateString)
  return date.toLocaleString('zh-CN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit'
  })
}
</script>